import itertools

def shortest_paths(adj, n):
    # Floyd-Warshall
    dist = [[float('inf')]*n for _ in range(n)]
    for i in range(n):
        dist[i][i] = 0
    for u in range(n):
        for v in adj[u]:
            dist[u][v] = 1
    for k in range(n):
        for i in range(n):
            for j in range(n):
                if dist[i][k] + dist[k][j] < dist[i][j]:
                    dist[i][j] = dist[i][k] + dist[k][j]
    return dist

n = 16
# start with path 0-1-2-...-15
edges = [(i, i+1) for i in range(n-1)]
adj = [[] for _ in range(n)]
for u, v in edges:
    adj[u].append(v)
    adj[v].append(u)

dist = shortest_paths(adj, n)

# candidate edges: opposite parity, distance >= 7 in current graph, not already edge
# We will try all possible edges and add if dist >= 7
candidates = []
for u in range(n):
    for v in range(u+1, n):
        if (u % 2) != (v % 2) and dist[u][v] >= 7:
            candidates.append((u, v))

print("Initial edges:", len(edges))
print("Candidates:", len(candidates))
print(candidates)

# Greedy add
added = []
for u, v in candidates:
    if dist[u][v] >= 7:
        # add edge
        adj[u].append(v)
        adj[v].append(u)
        # recompute distances
        dist = shortest_paths(adj, n)
        added.append((u,v))
        edges.append((u,v))

print("Added edges:", len(added))
print("Total edges:", len(edges))
print("Added:", added)

