# compute shortest cycle length
def girth(adj, n):
    best = float('inf')
    for s in range(n):
        # BFS from s
        dist = [float('inf')]*n
        parent = [-1]*n
        dist[s] = 0
        q = [s]
        while q:
            u = q.pop(0)
            for v in adj[u]:
                if dist[v] == float('inf'):
                    dist[v] = dist[u] + 1
                    parent[v] = u
                    q.append(v)
                elif parent[u] != v and parent[v] != u:
                    # found a cycle
                    # length = dist[u] + dist[v] + 1
                    cycle_len = dist[u] + dist[v] + 1
                    if cycle_len < best:
                        best = cycle_len
    return best if best != float('inf') else None

g = girth(adj, n)
print("Girth:", g)

# Check 4-colorability via backtracking
def is_colorable(adj, n, k):
    colors = [-1]*n
    order = sorted(range(n), key=lambda x: -len(adj[x]))
    def dfs(idx):
        if idx == n:
            return True
        u = order[idx]
        # assign color to u
        used = [False]*k
        for v in adj[u]:
            if colors[v] != -1:
                used[colors[v]] = True
        for c in range(k):
            if not used[c]:
                colors[u] = c
                if dfs(idx+1):
                    return True
                colors[u] = -1
        return False
    return dfs(0)

print("4-colorable:", is_colorable(adj, n, 4))
print("3-colorable:", is_colorable(adj, n, 3))
print("2-colorable:", is_colorable(adj, n, 2))

