import itertools

def girth(adj, n):
    best = float('inf')
    for s in range(n):
        dist = [float('inf')]*n
        parent = [-1]*n
        dist[s] = 0
        q = [s]
        while q:
            u = q.pop(0)
            for v in adj[u]:
                if dist[v] == float('inf'):
                    dist[v] = dist[u] + 1
                    parent[v] = u
                    q.append(v)
                elif parent[u] != v:
                    cycle_len = dist[u] + dist[v] + 1
                    if cycle_len < best:
                        best = cycle_len
    return best if best != float('inf') else None

def is_colorable(adj, n, k):
    colors = [-1]*n
    order = sorted(range(n), key=lambda x: -len(adj[x]))
    def dfs(idx):
        if idx == n:
            return True
        u = order[idx]
        used = [False]*k
        for v in adj[u]:
            if colors[v] != -1:
                used[colors[v]] = True
        for c in range(k):
            if not used[c]:
                colors[u] = c
                if dfs(idx+1):
                    return True
                colors[u] = -1
        return False
    return dfs(0)

n = 16
base_edges = [(i, (i+1)%n) for i in range(n)]
all_pairs = list(itertools.combinations(range(n), 2))
cycle_edges = set(base_edges)
chords = [e for e in all_pairs if e not in cycle_edges and (e[1], e[0]) not in cycle_edges]

def chord_cycles(chord, n):
    u, v = chord
    d1 = (v - u) % n
    d2 = (u - v) % n
    return min(d1, d2) + 1, max(d1, d2) + 1

valid_chords = []
for c in chords:
    l1, l2 = chord_cycles(c, n)
    if l1 >= 8 and l2 >= 8:
        valid_chords.append(c)

print("Valid chords:", len(valid_chords))
print(valid_chords)

# Try combinations of 4 valid chords
found = False
for combo in itertools.combinations(valid_chords, 4):
    edges = list(base_edges) + list(combo)
    adj = [[] for _ in range(n)]
    for u, v in edges:
        adj[u].append(v)
        adj[v].append(u)
    g = girth(adj, n)
    if g is not None and g >= 8 and is_colorable(adj, n, 4):
        print("FOUND!")
        print("Edges:", len(edges))
        print("Girth:", g)
        print(sorted(edges))
        found = True
        break

if not found:
    print("No solution with 4 chords")
